// The C allocator, not `PyMem_*`: Kotlin must be able to stage a C string before it holds the GIL,
// and `PyMem_Malloc` requires an attached thread state. This is also the only allocation path that
// exists here -- `withScopedMemoryAllocator` must never be called on this target, because it
// allocates from address 0 upward, directly on top of Emscripten's static data. CPython allocates;
// Kotlin only dereferences addresses it was handed.
@WasmImport(MODULE, "malloc")
external fun malloc(size: Int): Int

@WasmImport(MODULE, "free")
external fun free(ptr: Int)


